// vn-09 (docs/seed-spec.md §11): pink noise with an unintelligible murmur, generated by code from the
// seed, never by Polly. The murmur is band-limited noise shaped by random syllable-length envelopes
// from three "voices", so it sounds like distant talk without a single word in it. Output: 16-bit
// little-endian mono PCM at 48 kHz, which `seed:voices` encodes to Ogg/Opus with ffmpeg.
import { createRng, seedFor } from "../photos/prng";

export const NOISE_SAMPLE_RATE = 48_000;
export const NOISE_DURATION_SEC = 8;

/** One-pole low-pass state. */
function lowPass(cutoffHz: number): (x: number) => number {
  const a = Math.exp((-2 * Math.PI * cutoffHz) / NOISE_SAMPLE_RATE);
  let y = 0;
  return (x) => {
    y = (1 - a) * x + a * y;
    return y;
  };
}

/** Syllable-like envelope: segments of 120-320 ms that rise and fall, with gaps. */
function envelope(rng: ReturnType<typeof createRng>, samples: number): Float64Array {
  const out = new Float64Array(samples);
  let at = Math.floor(rng.range(0, 0.3) * NOISE_SAMPLE_RATE);
  while (at < samples) {
    const length = Math.floor(rng.range(0.12, 0.32) * NOISE_SAMPLE_RATE);
    const peak = rng.range(0.4, 1);
    for (let i = 0; i < length && at + i < samples; i += 1) out[at + i] = peak * Math.sin((Math.PI * i) / length);
    at += length + Math.floor(rng.range(0.03, 0.25) * NOISE_SAMPLE_RATE);
  }
  return out;
}

/** The PCM of vn-09: same seed, same bytes. */
export function noisePcm(): Buffer {
  const rng = createRng(seedFor("voice", "vn-09"));
  const samples = NOISE_SAMPLE_RATE * NOISE_DURATION_SEC;
  // Pink noise (Paul Kellet's filter over white noise).
  let b0 = 0;
  let b1 = 0;
  let b2 = 0;
  let b3 = 0;
  let b4 = 0;
  let b5 = 0;
  let b6 = 0;
  const voices = [0, 1, 2].map(() => ({ env: envelope(rng, samples), band: lowPass(rng.range(500, 900)), floor: lowPass(rng.range(120, 200)) }));
  const mix = new Float64Array(samples);
  let peak = 0;
  for (let n = 0; n < samples; n += 1) {
    const white = rng.range(-1, 1);
    b0 = 0.99886 * b0 + white * 0.0555179;
    b1 = 0.99332 * b1 + white * 0.0750759;
    b2 = 0.969 * b2 + white * 0.153852;
    b3 = 0.8665 * b3 + white * 0.3104856;
    b4 = 0.55 * b4 + white * 0.5329522;
    b5 = -0.7616 * b5 - white * 0.016898;
    const pink = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362) * 0.11;
    b6 = white * 0.115926;
    let murmur = 0;
    for (const voice of voices) {
      const source = rng.range(-1, 1);
      murmur += (voice.band(source) - voice.floor(source)) * (voice.env[n] ?? 0);
    }
    const fade = Math.min(1, n / 2400, (samples - n) / 2400);
    const value = (0.45 * pink + 2.2 * murmur) * fade;
    mix[n] = value;
    peak = Math.max(peak, Math.abs(value));
  }
  const gain = peak === 0 ? 0 : (0.5 * 32767) / peak;
  const pcm = Buffer.alloc(samples * 2);
  for (let n = 0; n < samples; n += 1) pcm.writeInt16LE(Math.round((mix[n] ?? 0) * gain), n * 2);
  return pcm;
}
